import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"27、【颐】 震下艮上","description":"温公易说 - 27、【颐】 震下艮上","frontmatter":{"title":"27、【颐】 震下艮上","description":"温公易说 - 27、【颐】 震下艮上"},"headers":[],"relativePath":"zh/classics/wengong/028.md","filePath":"zh/classics/wengong/028.md"}'),n={name:"zh/classics/wengong/028.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_27、【颐】-震下艮上" tabindex="-1">27、【颐】 震下艮上 <a class="header-anchor" href="#_27、【颐】-震下艮上" aria-label="Permalink to “27、【颐】 震下艮上”">​</a></h1><h3 id="彖曰-颐-贞吉-养正则吉也。观颐-观其所养也。自求口实-观其自养也。天地养万物-圣人养贤以及万民。颐之时大矣哉。" tabindex="-1">彖曰：颐，贞吉，养正则吉也。观颐，观其所养也。自求口实，观其自养也。天地养万物，圣人养贤以及万民。颐之时大矣哉。 <a class="header-anchor" href="#彖曰-颐-贞吉-养正则吉也。观颐-观其所养也。自求口实-观其自养也。天地养万物-圣人养贤以及万民。颐之时大矣哉。" aria-label="Permalink to “彖曰：颐，贞吉，养正则吉也。观颐，观其所养也。自求口实，观其自养也。天地养万物，圣人养贤以及万民。颐之时大矣哉。”">​</a></h3><p>凡万物有者为阳，无者为阴。日光之所灼者为阳，所不灼者为阴。和气之所煦者为阳，所不煦者为阴。圣人之于仁义，犹是也。爱养万物谓之仁，其所不爱不养谓之义。义者，裁仁以就宜者也。或曰：圣人之仁无不及也，而有不爱不养乎？曰：暴乱而为物害者，圣人所不得而爱养也。圣人岂乐杀哉？何谓观其所养？其人贤则其所养必贤也，其人不肖则所养必不肖也。何谓观其自养？取于人以义，自奉养以礼，斯贤也。取于人无度，自奉养无节，斯不肖也。故富视其所与，贫视其所取，穷视其所主，达视其所举，足以知其为人矣。</p><h3 id="象曰-山下有雷-颐。君子以慎言语-节饮食。" tabindex="-1">象曰：山下有雷，颐。君子以慎言语，节饮食。 <a class="header-anchor" href="#象曰-山下有雷-颐。君子以慎言语-节饮食。" aria-label="Permalink to “象曰：山下有雷，颐。君子以慎言语，节饮食。”">​</a></h3><h3 id="初九-捨尔灵观-我朵颐-凶-象曰-观我朵颐-亦不足贵也。" tabindex="-1">初九：捨尔灵观，我朵颐，凶 象曰：观我朵颐，亦不足贵也。 <a class="header-anchor" href="#初九-捨尔灵观-我朵颐-凶-象曰-观我朵颐-亦不足贵也。" aria-label="Permalink to “初九：捨尔灵观，我朵颐，凶 象曰：观我朵颐，亦不足贵也。”">​</a></h3><h3 id="六二-颠颐-拂经于丘颐-征凶-象曰-六二征凶-行失类也。" tabindex="-1">六二：颠颐，拂经于丘颐，征凶 象曰：六二征凶，行失类也。 <a class="header-anchor" href="#六二-颠颐-拂经于丘颐-征凶-象曰-六二征凶-行失类也。" aria-label="Permalink to “六二：颠颐，拂经于丘颐，征凶 象曰：六二征凶，行失类也。”">​</a></h3><h3 id="六三-拂颐-贞凶-十年勿用-无攸利-象曰-十年勿用-道大悖也。" tabindex="-1">六三：拂颐，贞凶，十年勿用，无攸利 象曰：十年勿用，道大悖也。 <a class="header-anchor" href="#六三-拂颐-贞凶-十年勿用-无攸利-象曰-十年勿用-道大悖也。" aria-label="Permalink to “六三：拂颐，贞凶，十年勿用，无攸利 象曰：十年勿用，道大悖也。”">​</a></h3><h3 id="六四-顚颐-吉。虎视眈眈-其欲逐逐-无咎-象曰-颠颐之吉-上施光也。" tabindex="-1">六四：顚颐，吉。虎视眈眈，其欲逐逐，无咎 象曰：颠颐之吉，上施光也。 <a class="header-anchor" href="#六四-顚颐-吉。虎视眈眈-其欲逐逐-无咎-象曰-颠颐之吉-上施光也。" aria-label="Permalink to “六四：顚颐，吉。虎视眈眈，其欲逐逐，无咎 象曰：颠颐之吉，上施光也。”">​</a></h3><h3 id="六五-拂经-居贞吉-不可涉大川-象曰-居贞之吉-顺以从上也。" tabindex="-1">六五：拂经，居贞吉，不可涉大川 象曰：居贞之吉，顺以从上也。 <a class="header-anchor" href="#六五-拂经-居贞吉-不可涉大川-象曰-居贞之吉-顺以从上也。" aria-label="Permalink to “六五：拂经，居贞吉，不可涉大川 象曰：居贞之吉，顺以从上也。”">​</a></h3><h3 id="上九-由颐-厉-吉-利涉大川-象曰-由颐厉吉-大有庆也。" tabindex="-1">上九：由颐，厉，吉，利涉大川 象曰：由颐厉吉，大有庆也。 <a class="header-anchor" href="#上九-由颐-厉-吉-利涉大川-象曰-由颐厉吉-大有庆也。" aria-label="Permalink to “上九：由颐，厉，吉，利涉大川 象曰：由颐厉吉，大有庆也。”">​</a></h3>',10)])])}const m=e(n,[["render",l]]);export{b as __pageData,m as default};
